  "source": "def investigate(context, acquire):
    values = context["values"]
    n = len(values)
    if n == 0:
        return 0
    contrib = []
    for i in range(n):
        x = values[i]
        p = x + x * x + x * x * x
        if i > 0:
            p = p + x * values[i - 1]
        contrib.append(p)
    for _ in range(4):
        total = 0
        for i in range(n):
            total = total + contrib[i]
            contrib[i] = total
    return contrib[-1]
